%[text] # Elevation Profile using Road Grade Profile block - Simulation Case
model_name = "HarnessModel_ElevationProfile";
load_system(model_name)
%%
%[text] Simulation conditions;
%[text] - Flat ground surface, i.e., 0 inclination angle. Then slight uphill. Then flat.
%[text] - Constant torque command to the motor drive unit. \
%[text] Road Grade Profile block
% setupHarness_ElevationProfile
RoadSurface.HorizontalDistance = simscape.Value([0 3 5, 7 8 9, 10 11 12], "km");
RoadSurface.GradePercent = [0 0 0, 2 2 2, 0 0 0];
RoadSurface.LeftElevation = simscape.Value(0, "m");

initial.HorizontalPosition = simscape.Value(0, "m");
%[text] Inputs
InputLUT.Brake.Time = seconds([0 1 2]);
InputLUT.Brake.Force = simscape.Value([0 0 0], "kN");

InputLUT.MotorDriveUnit.Time = seconds([0 1 300,  310 320 395,  400 410 545,  550 590 600,  701 990 1000]);
InputLUT.MotorDriveUnit.Torque = simscape.Value([25 25 25, 28 28 28, 35 35 35, 24 24 24, 20 20 20], "N*m");
%%
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "1000");

% applyToModel(sim_in)
%[text] Run simulation.
sim_out = sim(sim_in);
result = bevutil1.SignalUtil.getTimetableFromLoggedSignal(sim_out.logsout);
%%
varnames = [
"Braking force"
"Torque command"
"Horizontal position"
"Elevation"
"Road grade"
"Vehicle speed"
"Vehicle force"
"G force"
"Battery charge"
"Battery current"
"Battery voltage"
"Motor current"
"Motor torque"
"Motor angular speed"
"Motor voltage"
];

function vec = get_simscapeValue_vector(tt, name)
logical_index = tt.Properties.VariableNames == name;
unit_text = string(tt.Properties.VariableUnits(logical_index));
vec = simscape.Value(tt.(name), unit_text);
end  % local function
%[text] Powers in each component
V_vehicle = get_simscapeValue_vector(result, "Vehicle speed");
F_vehicle = get_simscapeValue_vector(result, "Vehicle force");
P_vehicle = convert(V_vehicle .* F_vehicle, "kW");
VehiclePowerTable = timetable(result.Time, P_vehicle, VariableNames="Vehicle power");

w_motor = get_simscapeValue_vector(result, "Motor angular speed");
trq_motor = get_simscapeValue_vector(result, "Motor torque");
P_motor = convert(w_motor .* trq_motor, "kW");
MotorPowerTable = timetable(result.Time, P_motor, VariableNames="Motor power");

i_battery = get_simscapeValue_vector(result, "Battery current");
v_battery = get_simscapeValue_vector(result, "Battery voltage");
P_battery = convert(i_battery .* v_battery, "kW");
BatteryPowerTable = timetable(result.Time, P_battery, VariableNames="Battery power");

bevutil1.SignalUtil.plotTimedData(TimedData=VehiclePowerTable, SignalName="Vehicle power", FigureHeight=200); %[output:4ef120bb]
bevutil1.SignalUtil.plotTimedData(TimedData=MotorPowerTable, SignalName="Motor power", FigureHeight=200); %[output:3ca2dfbb]
bevutil1.SignalUtil.plotTimedData(TimedData=BatteryPowerTable, SignalName="Battery power", FigureHeight=200); %[output:98d226e3]
%%
%[text] Plot logged signals
for k = 1 : numel(varnames) %[output:group:1b439f08]
  bevutil1.SignalUtil.plotTimedData(TimedData=result, SignalName=varnames(k), FigureHeight=200); %[output:255f3a5f] %[output:6b8f5ce2] %[output:046ae920] %[output:1e363776] %[output:1d361af8] %[output:27798468] %[output:1eb63744] %[output:72339639] %[output:411e77a5] %[output:42dc8be3] %[output:4e577e7c] %[output:7ce06639] %[output:0ec5c943] %[output:6110c7bb] %[output:6f49959d]
end  % for %[output:group:1b439f08]
